<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import AdminShell from '@/layouts/AdminShell.vue'
import http, { getErrorMessage } from '@/api/http'
import type { Role } from '../types'
const roles = ref<Role[]>([]); const error = ref(''); const modalOpen = ref(false); const saving = ref(false); const name = ref(''); const description = ref(''); const selected = ref<Role | null>(null); const submitted = ref(false)
const systemRoles = computed(() => roles.value.filter(role => role.is_system).length); const customRoles = computed(() => roles.value.filter(role => !role.is_system).length)
async function load() { try { roles.value = (await http.get<Role[]>('/roles')).data } catch (exception) { error.value = getErrorMessage(exception) } }
function openCreate() { selected.value = null; name.value = ''; description.value = ''; submitted.value = false; error.value = ''; modalOpen.value = true }
function openEdit(role: Role) { selected.value = role; name.value = role.name; description.value = role.description ?? ''; submitted.value = false; error.value = ''; modalOpen.value = true }
async function save() { submitted.value = true; if (!selected.value && !/^[a-z_]{3,80}$/.test(name.value)) return; saving.value = true; error.value = ''; try { if (selected.value) await http.patch(`/roles/${selected.value.id}`, { description: description.value || null }); else await http.post('/roles', { name: name.value, description: description.value || null }); modalOpen.value = false; await load() } catch (exception) { error.value = getErrorMessage(exception) } finally { saving.value = false } }
async function remove(role: Role) { if (!confirm(`¿Eliminar el rol “${role.name}”? Esta acción no se puede deshacer.`)) return; try { await http.delete(`/roles/${role.id}`); await load() } catch (exception) { error.value = getErrorMessage(exception) } }
onMounted(load)
</script>
<template><AdminShell><section class="page-heading"><div><p class="eyebrow">Identidad y acceso</p><h1>Roles y permisos</h1><p>Define cómo se organiza el acceso de cada persona dentro del taller.</p></div><button class="primary-button" @click="openCreate">＋ Nuevo rol</button></section><section class="metrics"><article><span>Roles totales</span><strong>{{ roles.length }}</strong></article><article><span>Roles de sistema</span><strong>{{ systemRoles }}</strong></article><article><span>Roles personalizados</span><strong>{{ customRoles }}</strong></article></section><p v-if="error" class="notice error">{{ error }}</p><section class="roles-grid"><article v-for="role in roles" :key="role.id" class="role-card"><div class="role-card-top"><span class="role-icon">{{ role.is_system ? '◈' : '＋' }}</span><span class="status" :class="role.is_system ? 'status-system' : 'status-custom'">{{ role.is_system ? 'Sistema' : 'Personalizado' }}</span></div><h2>{{ role.name.replaceAll('_', ' ') }}</h2><p>{{ role.description || 'Sin descripción definida.' }}</p><div class="role-card-actions"><button v-if="!role.is_system" class="table-action" @click="openEdit(role)">Editar descripción</button><span v-else class="locked-label">Protegido</span><button v-if="!role.is_system" class="table-action danger-action" @click="remove(role)">Eliminar</button></div></article></section><div v-if="modalOpen" class="modal-backdrop" @click.self="modalOpen = false"><section class="modal-card" role="dialog" aria-modal="true"><div class="modal-title"><div><p class="eyebrow">{{ selected ? 'Edición' : 'Configuración' }}</p><h2>{{ selected ? 'Editar rol' : 'Crear rol' }}</h2></div><button class="close-button" aria-label="Cerrar" @click="modalOpen = false">×</button></div><form class="modal-form" @submit.prevent="save"><label>Identificador del rol<input v-model.trim="name" :disabled="Boolean(selected)" placeholder="ej. jefe_operaciones" /><small v-if="!selected">Sólo minúsculas y guiones bajos.</small><span v-if="submitted && !selected && !/^[a-z_]{3,80}$/.test(name)">Usa de 3 a 80 caracteres en minúsculas.</span></label><label>Descripción<textarea v-model.trim="description" rows="4" placeholder="Describe las responsabilidades de este rol"></textarea></label><div class="modal-actions"><button type="button" class="secondary-button" @click="modalOpen = false">Cancelar</button><button class="primary-button" type="submit" :disabled="saving">{{ saving ? 'Guardando…' : 'Guardar rol' }}</button></div></form></section></div></AdminShell></template>
